{"source":"
{% include 'Wrapper Ajax Template' %}
{% block main %}
{% include 'QSPasswordEncryption' %}
{% editable page 'adx_copy' type: 'html', liquid: true %}

{% assign iscompliance = false %}
{% if request.params['registrationid'] %}
{% assign registrationid = request.params['registrationid'] %}
{% assign iscompliance = true %}
{% endif %}

{% if request.params['contactid'] %}
{% assign contactid = request.params['contactid'] %}
{% assign contact = entities['contact'][contactid] %}
{% assign contactEmail = contact.emailaddress1 %}
{% assign new_iscompliancecomplete = contact.new_iscompliancecomplete %}
{% assign new_iscandidate = contact.new_iscandidate %}

{% endif %}

<style>

  .modal {
    display: none;
    position: fixed;
    z-index: 1;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    overflow: auto;
    background-color: rgb(0,0,0);
    background-color: rgba(0,0,0,0.4);
  }

  .modal-content {
    background-color: #fefefe;
    margin: 15% auto;
    padding: 20px;
    border: 1px solid #888;
    width: 30%;
    border-radius: 4px;
    box-shadow: 0 5px 15px rgba(0,0,0,0.3);
  }

  .close {
    color: #37393B;
    float: right;
    font-size: 24px;
    font-weight: bold;
  }

  .close:hover,
  .close:focus {
    color: black;
    text-decoration: none;
    cursor: pointer;
  }

  .modal-content h4 {
    margin-top: 0;
    margin-bottom: 15px;
    font-size: 20px;
  }

  .modal-content p {
    font-size: 16px;
  }

  /* OK Button */
  #closeModalButton {
    background-color: #37393B;
    border: none;
    color: white;
    padding: 5px 17px;
    text-align: center;
    text-decoration: none;
    display: inline-block;
    font-size: 16px;
    margin-top: 20px;
    cursor: pointer;
    border-radius: 4px;
  }

  #closeModalButton:hover {
    background-color: #555;
  }

  .error-box {
    background-color: #eddcdc !important ;
    color: #175f96;
    width: 36%;
    padding: 10px;
    margin-top: 10px;
    margin-bottom: 20px;
    display: none;
    cursor: pointer;
    font-size: 14px;
  }

  .error-box:hover {
    text-decoration: underline;
  }

  .tab {
    overflow: hidden;
    border: 1px solid #ccc;
    background-color: #f1f1f1;
  }

  .username {
    margin-right: 25px;
  }

  .password {
    margin-right: 33px;
  }

  .email {
    margin-right: 60px;
  }

  .tab button {
    background-color: inherit;
    float: left;
    border: none;
    outline: none;
    cursor: pointer;
    padding: 14px 16px;
    transition: 0.3s;
    font-size: 17px;
  }

  .tab button:hover {
    background-color: #ddd;
  }

  .tab button.active {
    background-color: #ccc;
    color: #006680;
  }

  .tabcontent {
    display: none;
    padding: 40px 75px;
    border: 1px solid #ccc;
    border-top: none;
  }

  .userInfo {
    margin-top: 20px;
  }

  #signInButton,
  #registerButton {
    border-color: #006680;
    border-radius: 2px;
    font-family: Arial;
    font-weight: 600;
    font-size: 14px;
    padding: 4px 15px;
    width: fit-content;
    border-style: solid;
    background-color: #006680;
    color: #FFFFFF;
  }

  input {
    padding: 6px 12px;
    width: 25%;
    border: 1px solid #949494;
  }

  button[disabled] {
    background-color: #F3F2F1 !important;
    color: #A19F9D !important;
    border: 2px !important;
    cursor: not-allowed !important;
    pointer-events: auto !important;
  }

  @media only screen and (max-width: 600px) {
    .userInfo {
      display: flex;
      flex-direction: column;
    }

    input {
      width: auto;
    }
  }
</style>
<div id="content-container" class="container wrapper-body" role="main">
  <div id="content">
    <div class="tab">
      <button class="tablinks " onclick="window.location.href='/qssignin'">Sign In</button>
      <button class="tablinks active" onclick="window.location.href='/registration'">Register</button>
    </div>

    <!-- Register Form -->
    <div id="Register" class="tabcontent" style="display: block;">
      <div class="userInfo">
        <div id="username-error" class="error-box" onclick="focusUsername()"></div>
        <label class="username" for="reg_username">User name</label>
        <input type="text" id="reg_username" name="reg_username" placeholder="Username" required><br>
      </div>
      <div class="userInfo">
        <label class="password" for="reg_password">Password</label>
        <input type="password" id="reg_password" name="reg_password" placeholder="Password" required><br>
      </div>
      <div class="userInfo">
        <label class="email" for="reg_email">Email</label>
        <input type="email" id="reg_email" name="reg_email" placeholder="Email" required><br>
      </div>
      <div class="userInfo">
        <button id="registerButton" type="button">Register</button>
      </div>
    </div>
  </div>

</div>

<div id="spaceErrorModal" class="modal">
  <div class="modal-content">
    <span class="close">&times;</span>
    <h4><img src="https://img.icons8.com/color/48/000000/error.png" alt="Warning Icon" style="vertical-align:middle; width:24px; height:24px; margin-right:8px;">Warning</h4>
    <p>There should be no spaces in the username.</p>
    <button id="closeModalButton">OK</button>
  </div>
</div>

<script type="text/javascript">

  // var contactEmail = "{{ contactEmail | escapejs }}";

  function focusUsername() {
    document.getElementById('reg_username').focus();
  }

  $(document).ready(function () {
    // Trigger click event on Enter key press for Register
    $('#reg_username, #reg_password, #reg_email').keypress(function (e) {
      if (e.which == 13) {
        $('#registerButton').click();
      }
    });

    console.log('Contactid', "{{ contactid }}");
    if ("{{ contactid }}" !== '') {
      // $('#reg_username').val('{{ contactEmail }}').prop('readonly', true);
      $('#reg_email').val('{{ contactEmail }}').prop('readonly', true);

      // Logging the values after setting them
      // var username = $('#reg_username').val();
      var email = $('#reg_email').val();
    }

    var modal = document.getElementById("spaceErrorModal");
    var closeModalButton = document.getElementById("closeModalButton");
    
    closeModalButton.onclick = function() {
      modal.style.display = "none";
    };

    document.getElementsByClassName("close")[0].onclick = function() {
      modal.style.display = "none";
    };

    window.onclick = function(event) {
      if (event.target == modal) {
        modal.style.display = "none";
      }
    };

    $('#registerButton').click(function () {
      var $this = $(this);
      var username = $('#reg_username').val();

      if (/\s/.test(username)) {
          modal.style.display = "block";
          return;
      }

      $('#username-error').hide();
      $this.prop('disabled', true).text('Registering...');

      // Define the base URL for checking username
      var currentPageUrl = window.location.href;
      var baseUrl = currentPageUrl.split('/').slice(0, 3).join('/');
      //unique email and userName
      var checkUsernameUrl = baseUrl + "/_api/cloudflow/v1.0/trigger/46452de0-0f5a-ef11-bfe3-002248cb952b";

      var flowData = {
        username: username
      };

      shell.ajaxSafePost({
        type: "POST",
        contentType: "application/json",
        url: checkUsernameUrl,
        data: JSON.stringify({ "eventData": JSON.stringify(flowData) }),
        processData: false,
        global: false
      })
      .done(function (response) {
        var result = JSON.parse(response);

        console.log('Parsed Result:', result);

        if (result.usernameexist === 'False') {
          $('#username-error').hide(); 
          proceedWithRegistration();
        } else {
          $('#username-error').text(`The username "${username}" is already taken.`).show();
          $this.prop('disabled', false).text('Register');
        }
      })
      .fail(function (error) {
        alert('Error during username check.');
        $this.prop('disabled', false).text('Register');
      });
    });

    function proceedWithRegistration() {
      var $this = $('#registerButton');
      var contactid = "{{ request.params['contactid'] }}";
      var username = $('#reg_username').val();
      var email = $('#reg_email').val();
      var password = $('#reg_password').val();

      // Generate a random salt
      // const salt = window.generateSalt();
      // console.log("salt: ", salt);

      window.hashPassword(password).then(hashedPassword => {
        console.log("Hashed Password:", hashedPassword);

        $this.prop('disabled', true).text('Registering...');

        var regData = {
          username: username,
          contactid: contactid,
          email: email,
          password: hashedPassword,
          // salt: salt
        };

        console.log("regData: ", regData);
        //register a contact
        var regUrl = window.location.origin + "/_api/cloudflow/v1.0/trigger/63a5f517-381c-ef11-840a-0022486a2752";

        shell.ajaxSafePost({
          type: "POST",
          contentType: "application/json",
          url: regUrl,
          data: JSON.stringify({ "eventData": JSON.stringify(regData) }),
          processData: false,
          global: false
        })
        .done(function (response) {
          var result = JSON.parse(response);

          if (result.processed === "True") {
            signIn(username, hashedPassword);
          } else {
            $('#username-error').text(result.errormessage || 'Registration failed. Please try again.').show();
            $this.prop('disabled', false).text('Register');
          }
        })
        .fail(function (error) {
          console.error('Error during registration request:', error);
          console.log("Status:", error.status); // Log the status code
          console.log("Response Text:", error.responseText); // Log the response text

          if (error.status === 502) {
            alert('The server is currently unavailable. Please try again later.');
          } else {
            alert('Registration failed. Please try again.');
          }

          $this.prop('disabled', false).text('Register');
        });
      });
    }


    function signIn(username, hashedPassword) {
      var $signInButton = $('#signInButton');

      // Disable the button and change its text to "Processing..."
      $signInButton.prop('disabled', true).text('Processing...');


      var currentPageUrl = window.location.href;
      // Extract the base URL
      var baseUrl = currentPageUrl.split('/').slice(0, 3).join('/');
      // Define the relative path to your API endpoint
      //authenticate userSession
      var relativePath = "_api/cloudflow/v1.0/trigger/84d5a7b7-4eb8-ee11-9078-6045bd0cfca3";

      // Construct the full URL by concatenating the base URL and the relative path 
      var flowUrl = baseUrl + "/" + relativePath;

      var flowData = {
        username: username,
        password: hashedPassword
      };

      console.log("Sending Sign-In Request:", flowData); // Log the sign-in request data

      shell.ajaxSafePost({
        type: "POST",
        contentType: "application/json",
        url: flowUrl,
        data: JSON.stringify({ "eventData": JSON.stringify(flowData) }),
        processData: false,
        global: false
      })
        .done(function (response) {
          // Parse the response
          var result = JSON.parse(response);

          if (result.authenticated === "False") {
            // Display specific error message
            alert(result.errormessage || 'Authentication failed. Please try again.');
            $signInButton.prop('disabled', false).text('Sign In');
          } else {
            // Store session information in local storage
            localStorage.setItem('QSsessionID', result.sessionid);
            localStorage.setItem('QSsessionExpiry', result.expiry);
            localStorage.setItem('QScontactFullName', result.fullname);
            localStorage.setItem('QScontactid', result.contactid);
            localStorage.setItem('QSclientid', result.clientid);
            var contactid = result.contactid;
            console.log("contactid:", contactid);

            $(document).trigger('userLoggedIn');

            console.log('isComplianceComplete:', '{{ new_iscompliancecomplete }}');
            console.log('isCandidate:', '{{new_iscandidate}}');
            console.log('iscompliance:', '{{iscompliance}}');
            console.log('Registrationid:', '{{registrationid}}');
            console.log('result.contactid:',result.contactid);
            console.log('result.clientid:',result.clientid);
            

            if (result.clientid) {
              window.location.href = '/assignments?contactid=' + result.contactid + '&' + 'clientid=' + result.clientid;
            } 
            else if ('{{registrationid}}' !== '' && '{{registrationid}}' !== null) {
              console.log('Redirecting to /personaldetails');
              window.location.href = '/personaldetails/?registrationid=' + '{{registrationid}}' + '&contactid='  + result.contactid;
            }
            else if (result.contactid) {
              window.location.href = '/candidatetimesheets?contactid=' + result.contactid;
            }
            
            document.addEventListener("DOMContentLoaded", function() {
              // Wait for the page to fully load
              window.addEventListener('load', function() {
                  // Reload the page after it has fully loaded with the new URL
                  window.location.reload();
              });
            });
                    }
        })
        .fail(function (error) {
          // Handle error here
          console.error('Error during authentication request:', error);
          alert('Error during authentication request.');
          $signInButton.prop('disabled', false).text('Sign In');
        });
        
    };
  });



</script>
{% endblock %}"}
